def handle(app, svc):
    resp = svc.apply(app)

    # API v2: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    # API v1: {"decision": "approve"/"decline"/"refer", "limit": int}
    if isinstance(resp, dict) and "result" in resp and isinstance(resp["result"], dict):
        outcome = resp["result"].get("outcome")
        limit = resp["result"].get("credit_limit", 0) or 0
    else:
        outcome = resp.get("decision") if isinstance(resp, dict) else None
        limit = (resp.get("limit", 0) or 0) if isinstance(resp, dict) else 0

    # Map v1 "refer" to v2 "manual_review"
    if outcome == "refer":
        outcome = "manual_review"

    # Network referral rule: self_employed with requested_limit > 6000
    # must not be issued; decline stays a decline; approve/refer -> queue_review.
    requested_limit = 0
    if isinstance(app, dict):
        try:
            requested_limit = int(app.get("requested_limit", 0) or 0)
        except (TypeError, ValueError):
            requested_limit = 0
    self_employed = (app or {}).get("employment") == "self_employed" if isinstance(app, dict) else False

    if self_employed and requested_limit > 6000:
        if outcome == "declined":
            return {"action": "decline", "limit": 0}
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": int(limit)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review (or unknown)
    return {"action": "queue_review", "limit": 0}

